-- Esquema de referencia PostgreSQL auditado 2026-11-24 y JPA c21f518. SOLO base nueva y descartable.
-- No ejecutar en el proyecto existente. No contiene datos iniciales.
BEGIN;
CREATE TABLE public.usuarios (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre varchar(255) NOT NULL,email varchar(255) NOT NULL UNIQUE,password varchar(255) NOT NULL,rol varchar(255) NOT NULL,activo boolean NOT NULL DEFAULT true);
CREATE TABLE public.peliculas (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,titulo varchar(150) NOT NULL,sinopsis varchar(2000),genero varchar(100) NOT NULL,duracion_minutos integer NOT NULL,clasificacion varchar(10) NOT NULL,fecha_estreno date NOT NULL,imagen_url varchar(1000),estado boolean NOT NULL);
CREATE TABLE public.salas (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre varchar(255) NOT NULL UNIQUE,filas integer NOT NULL,columnas integer NOT NULL);
CREATE TABLE public.asientos (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,fila varchar(1) NOT NULL,numero integer NOT NULL,sala_id bigint NOT NULL REFERENCES public.salas(id),CONSTRAINT uk_asiento_sala_fila_numero UNIQUE(sala_id,fila,numero));
CREATE TABLE public.funciones (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,pelicula_id bigint NOT NULL REFERENCES public.peliculas(id),sala_id bigint NOT NULL REFERENCES public.salas(id),fecha_hora timestamp NOT NULL,fecha_hora_fin timestamp NOT NULL,precio numeric(10,2) NOT NULL,cancelada boolean NOT NULL DEFAULT false);
CREATE TABLE public.productos (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre varchar(255) NOT NULL,categoria varchar(20) NOT NULL,precio numeric(10,2) NOT NULL,activo boolean NOT NULL DEFAULT true);
CREATE TABLE public.ordenes (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,usuario_id bigint NOT NULL REFERENCES public.usuarios(id),estado varchar(20) NOT NULL DEFAULT 'PENDIENTE',total numeric(10,2) NOT NULL DEFAULT 0,fecha_creacion timestamp NOT NULL DEFAULT localtimestamp);
CREATE TABLE public.entradas (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,orden_id bigint NOT NULL REFERENCES public.ordenes(id),funcion_id bigint NOT NULL REFERENCES public.funciones(id),asiento_id bigint NOT NULL REFERENCES public.asientos(id),precio_unitario numeric(10,2) NOT NULL,CONSTRAINT uk_entrada_funcion_asiento UNIQUE(funcion_id,asiento_id));
CREATE TABLE public.detalle_productos (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,orden_id bigint NOT NULL REFERENCES public.ordenes(id),producto_id bigint NOT NULL REFERENCES public.productos(id),cantidad integer NOT NULL,precio_unitario numeric(10,2) NOT NULL);
CREATE TABLE public.notificaciones (id bigserial PRIMARY KEY,usuario_id bigint NOT NULL REFERENCES public.usuarios(id),mensaje varchar(500) NOT NULL,leida boolean NOT NULL DEFAULT false,fecha_creacion timestamp NOT NULL DEFAULT now());
-- En una base nueva no se concede acceso directo por Data API.
ALTER TABLE public.usuarios ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.peliculas ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.salas ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.asientos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.funciones ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.productos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ordenes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.entradas ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.detalle_productos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notificaciones ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.usuarios ADD CONSTRAINT ck_usuarios_nombre CHECK (btrim(nombre) <> '');
ALTER TABLE public.usuarios ADD CONSTRAINT ck_usuarios_rol CHECK (rol IN ('ADMIN','CLIENTE'));
ALTER TABLE public.peliculas ADD CONSTRAINT ck_peliculas_titulo CHECK (btrim(titulo) <> '');
ALTER TABLE public.peliculas ADD CONSTRAINT ck_peliculas_genero CHECK (btrim(genero) <> '');
ALTER TABLE public.peliculas ADD CONSTRAINT ck_peliculas_duracion CHECK (duracion_minutos > 0);
ALTER TABLE public.peliculas ADD CONSTRAINT ck_peliculas_clasificacion CHECK (clasificacion IN ('APT','+12','+14','+18'));
ALTER TABLE public.salas ADD CONSTRAINT ck_salas_nombre CHECK (btrim(nombre) <> '');
ALTER TABLE public.salas ADD CONSTRAINT ck_salas_filas CHECK (filas BETWEEN 1 AND 26);
ALTER TABLE public.salas ADD CONSTRAINT ck_salas_columnas CHECK (columnas BETWEEN 1 AND 50);
ALTER TABLE public.asientos ADD CONSTRAINT ck_asientos_fila CHECK (fila ~ '^[A-Z]$');
ALTER TABLE public.asientos ADD CONSTRAINT ck_asientos_numero CHECK (numero > 0);
ALTER TABLE public.funciones ADD CONSTRAINT ck_funciones_horario CHECK (fecha_hora_fin > fecha_hora);
ALTER TABLE public.funciones ADD CONSTRAINT ck_funciones_precio CHECK (precio > 0);
ALTER TABLE public.productos ADD CONSTRAINT ck_productos_nombre CHECK (btrim(nombre) <> '');
ALTER TABLE public.productos ADD CONSTRAINT ck_productos_categoria CHECK (categoria IN ('CANCHITA','BEBIDA','DULCE','COMBO'));
ALTER TABLE public.productos ADD CONSTRAINT ck_productos_precio CHECK (precio > 0);
ALTER TABLE public.ordenes ADD CONSTRAINT ck_ordenes_estado CHECK (estado IN ('PENDIENTE','PAGADA','CANCELADA'));
ALTER TABLE public.ordenes ADD CONSTRAINT ck_ordenes_total CHECK (total >= 0);
ALTER TABLE public.entradas ADD CONSTRAINT ck_entradas_precio CHECK (precio_unitario > 0);
ALTER TABLE public.detalle_productos ADD CONSTRAINT ck_detalle_productos_cantidad CHECK (cantidad > 0);
ALTER TABLE public.detalle_productos ADD CONSTRAINT ck_detalle_productos_precio CHECK (precio_unitario >= 0);
CREATE INDEX ix_peliculas_estado_estreno ON public.peliculas(estado, fecha_estreno);
CREATE INDEX ix_funciones_pelicula_fecha ON public.funciones(pelicula_id, fecha_hora);
CREATE INDEX ix_funciones_sala ON public.funciones(sala_id);
CREATE INDEX ix_ordenes_usuario_fecha ON public.ordenes(usuario_id, fecha_creacion DESC);
CREATE INDEX ix_entradas_orden ON public.entradas(orden_id);
CREATE INDEX ix_entradas_asiento ON public.entradas(asiento_id);
CREATE INDEX ix_detalle_productos_orden ON public.detalle_productos(orden_id);
CREATE INDEX ix_detalle_productos_producto ON public.detalle_productos(producto_id);
CREATE INDEX idx_notificaciones_usuario_leida ON public.notificaciones(usuario_id, leida);
-- Reproducir el cierre de acceso Data API si los roles existen (Supabase).
DO $$ DECLARE r text; BEGIN
 FOREACH r IN ARRAY ARRAY['anon','authenticated'] LOOP
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname=r) THEN
   EXECUTE format('REVOKE ALL ON TABLE public.usuarios,public.peliculas,public.salas,public.asientos,public.funciones,public.productos,public.ordenes,public.entradas,public.detalle_productos,public.notificaciones FROM %I',r);
  END IF;
 END LOOP;
END $$;
COMMIT;
